// ── KaniHasher hash leaves (single u64 state word; exact write replays) ──
const CW_KANI_MAGIC: u64 = 0x517cc1b727220a95;
extern "C" fn cw_shim_hash_u32(value: *const u32, state: *mut u64) {
    unsafe {
        let i = *value as u64;
        let s = (*state) ^ i;
        *state = s.wrapping_mul(CW_KANI_MAGIC);
    }
}
extern "C" fn cw_shim_hash_u64(value: *const u64, state: *mut u64) {
    unsafe {
        let i = *value;
        let s = (*state) ^ i;
        *state = s.wrapping_mul(CW_KANI_MAGIC);
    }
}
extern "C" fn cw_shim_hash_isize(value: *const isize, state: *mut u64) {
    unsafe {
        let i = *value as u64;
        let s = (*state) ^ i;
        *state = s.wrapping_mul(CW_KANI_MAGIC);
    }
}
// core::mem::discriminant::<Level> — sret Discriminant<Level> (8 bytes).
extern "C" fn cw_shim_discriminant_level(
    sret: *mut std::mem::Discriminant<rn::Level>,
    this: *const rn::Level,
) {
    unsafe {
        std::ptr::write(sret, std::mem::discriminant(&*this));
    }
}
// KaniHasher write replays through the mirror's semantics.
struct CwShimKani {
    state: u64,
}
impl std::hash::Hasher for CwShimKani {
    fn finish(&self) -> u64 {
        self.state
    }
    fn write(&mut self, bytes: &[u8]) {
        for &b in bytes {
            self.state = self.state.wrapping_mul(31).wrapping_add(b as u64);
        }
    }
    fn write_u8(&mut self, i: u8) {
        self.state ^= i as u64;
        self.state = self.state.wrapping_mul(CW_KANI_MAGIC);
    }
    fn write_u16(&mut self, i: u16) {
        self.state ^= i as u64;
        self.state = self.state.wrapping_mul(CW_KANI_MAGIC);
    }
    fn write_u32(&mut self, i: u32) {
        self.state ^= i as u64;
        self.state = self.state.wrapping_mul(CW_KANI_MAGIC);
    }
    fn write_u64(&mut self, i: u64) {
        self.state ^= i;
        self.state = self.state.wrapping_mul(CW_KANI_MAGIC);
    }
    fn write_u128(&mut self, i: u128) {
        self.write_u64(i as u64);
        self.write_u64((i >> 64) as u64);
    }
    fn write_usize(&mut self, i: usize) {
        self.write_u64(i as u64);
    }
}
// <Discriminant<Level> as Hash>::hash — replay core's impl through KaniHasher.
extern "C" fn cw_shim_hash_discriminant_level(
    value: *const std::mem::Discriminant<rn::Level>,
    state: *mut u64,
) {
    use std::hash::{Hash, Hasher};
    unsafe {
        let mut h = CwShimKani { state: *state };
        (*value).hash(&mut h);
        *state = h.finish();
    }
}
// <Arc<Level> as Hash>::hash == <Level as Hash>::hash(&**arc) — replay the full
// mirror Level hash (discriminant + children; Param writes the REAL Name
// cached_hash) seeded with the current state.
extern "C" fn cw_shim_hash_arc_level(arcptr: *const Arc<rn::Level>, state: *mut u64) {
    use std::hash::{Hash, Hasher};
    unsafe {
        let lvl: &rn::Level = &*(*arcptr);
        let mut h = CwShimKani { state: *state };
        lvl.hash(&mut h);
        *state = h.finish();
    }
}

// Extern symbol map. The crate tag is load-bearing (v0 mangling, derived from
// the slice crate name `clean_ctx_whnf_slice` — tag `Cs3ElTAlJBXdV_20…`, with
// backref indices that DIFFER from R8's because the crate name length
// changed); every symbol below was read VERBATIM off the emitted modules'
// bodyless fns (union over all three fixtures), and jit_module() fail-louds
// if any emitted extern is missing.
